from typing import List


class Solution:
    def countWinningSequences(self, s: str) -> int:
        mod = 10**9 + 7
        n = len(s)
        moves = "FWE"
        beats = {"F": "E", "W": "F", "E": "W"}
        offset = n + 1
        size = 2 * n + 3

        def score(bob, alice):
            if beats[bob] == alice:
                return 1
            if beats[alice] == bob:
                return -1
            return 0

        dp = []
        for b in moves:
            row = [0] * size
            row[offset + score(b, s[0])] = 1
            dp.append(row)
        for i in range(1, n):
            new_dp = []
            for bi, b in enumerate(moves):
                p1, p2 = [dp[j] for j in range(3) if j != bi]
                merged = [(x + y) % mod for x, y in zip(p1, p2)]
                delta = score(b, s[i])
                if delta == 1:
                    merged = [0] + merged[:-1]
                elif delta == -1:
                    merged = merged[1:] + [0]
                new_dp.append(merged)
            dp = new_dp
        result = 0
        for row in dp:
            result += sum(row[offset + 1:])
        return result % mod

